UPDATE "Category" SET translations = '{"hi": {"name": "रेज़िन फ़र्नीचर और सतहें", "description": "रिवर टेबल, साइड और कॉफ़ी टेबल, कंसोल और टेबल टॉप, वॉर्डरोब और सतह पैनल — लकड़ी के साथ एपॉक्सी, आपके नाप के अनुसार। प्रीमियम श्रेणी।"}, "gu": {"name": "રેઝિન ફર્નિચર અને સપાટીઓ", "description": "રિવર ટેબલ, સાઇડ અને કૉફી ટેબલ, કન્સોલ અને ટેબલ ટૉપ, વૉર્ડરોબ અને સપાટી પેનલ — લાકડા સાથે ઇપોક્સી, તમારા માપ પ્રમાણે. પ્રીમિયમ શ્રેણી."}, "ar": {"name": "أثاث وأسطح الراتنج", "description": "طاولات نهرية، طاولات جانبية وقهوة، أسطح كونسول وطاولات، وألواح خزائن وأسطح — إيبوكسي مع الخشب، حسب مقاساتك. فئة فاخرة."}, "es": {"name": "Muebles y superficies de resina", "description": "Mesas río, mesas auxiliares y de café, consolas y tableros, paneles para armarios y superficies — epoxi con madera, a tus medidas. Gama premium."}, "de": {"name": "Harzmöbel & Oberflächen", "description": "River Tables, Beistell- und Couchtische, Konsolen- und Tischplatten, Schrank- und Flächenpaneele — Epoxid mit Holz, nach Ihren Maßen. Premium-Klasse."}, "fr": {"name": "Mobilier & surfaces en résine", "description": "Tables rivière, tables d''appoint et basses, consoles et plateaux, panneaux d''armoire et de surface — époxy et bois, à vos dimensions. Gamme premium."}, "zh": {"name": "树脂家具与台面", "description": "河流桌、边桌与咖啡桌、玄关桌与桌面、衣柜及台面板 — 环氧树脂与木材结合，按您的尺寸定制。高端系列。"}, "ja": {"name": "レジン家具・天板", "description": "リバーテーブル、サイド・コーヒーテーブル、コンソール・天板、収納パネルなど — 木材とエポキシを組み合わせ、ご希望の寸法で製作。プレミアムライン。"}}'::jsonb WHERE slug = 'resin-furniture-surfaces' AND translations IS NULL;
UPDATE "Category" SET translations = '{"hi": {"name": "कला और शिल्प कृतियाँ", "description": "समुद्र, जिओड और अमूर्त वॉल आर्ट, रेज़िन पेंटिंग और एक-से-एक सजावटी कृतियाँ।"}, "gu": {"name": "કલા અને હસ્તકલા કૃતિઓ", "description": "સમુદ્ર, જિયોડ અને અમૂર્ત વૉલ આર્ટ, રેઝિન પેઇન્ટિંગ અને અનોખી સુશોભન કૃતિઓ."}, "ar": {"name": "قطع فنية وحرفية", "description": "لوحات جدارية بأنماط المحيط والجيود والتجريد، ولوحات راتنج وقطع زخرفية فريدة."}, "es": {"name": "Piezas de arte y artesanía", "description": "Arte mural de océano, geoda y abstracto, pinturas en resina y piezas decorativas únicas."}, "de": {"name": "Kunst- & Handwerksstücke", "description": "Ozean-, Geoden- und abstrakte Wandkunst, Harzgemälde und dekorative Unikate."}, "fr": {"name": "Pièces d''art & artisanat", "description": "Art mural océan, géode et abstrait, peintures en résine et pièces décoratives uniques."}, "zh": {"name": "艺术与手工作品", "description": "海洋、晶洞与抽象墙面艺术、树脂画及独一无二的装饰作品。"}, "ja": {"name": "アート・クラフト作品", "description": "オーシャン・ジオード・抽象のウォールアート、レジン絵画、一点ものの装飾作品。"}}'::jsonb WHERE slug = 'art-craft-pieces' AND translations IS NULL;
UPDATE "Category" SET translations = '{"hi": {"name": "वरमाला संरक्षण", "description": "कई आकारों में म्यूज़ियम-स्तरीय शादी की वरमाला संरक्षण फ़्रेम — फ़्रेम फ़िनिश, बैकिंग रंग, नाम-तारीख़ उत्कीर्णन, फ़ोटो इनसेट।"}, "gu": {"name": "વરમાળા જતન", "description": "અનેક કદમાં મ્યુઝિયમ-કક્ષાના લગ્નની વરમાળા જતન ફ્રેમ — ફ્રેમ ફિનિશ, બેકિંગ રંગ, નામ-તારીખ કોતરણી, ફોટો ઇનસેટ."}, "ar": {"name": "حفظ أكاليل الزفاف", "description": "إطارات حفظ أكاليل الزفاف بجودة متحفية وبمقاسات متعددة — تشطيب الإطار، لون الخلفية، نقش الاسم والتاريخ، وإدراج صورة."}, "es": {"name": "Preservación de varmala", "description": "Marcos de preservación de guirnaldas nupciales con calidad de museo, en varios tamaños — acabado del marco, color de fondo, grabado de nombres y fecha, foto insertada."}, "de": {"name": "Varmala-Konservierung", "description": "Museumsreife Rahmen zur Konservierung von Hochzeitsgirlanden in mehreren Größen — Rahmenfinish, Hintergrundfarbe, Namens- und Datumsgravur, Fotoeinsatz."}, "fr": {"name": "Préservation de varmala", "description": "Cadres de préservation de guirlandes de mariage de qualité musée, en plusieurs tailles — finition du cadre, couleur du fond, gravure des noms et de la date, photo insérée."}, "zh": {"name": "婚礼花环封存", "description": "博物馆级婚礼花环封存相框，多种尺寸可选 — 相框饰面、底衬颜色、姓名与日期镌刻、照片镶嵌。"}, "ja": {"name": "バルマラ保存", "description": "ミュージアム品質の結婚式ガーランド保存フレーム。サイズ多数 — フレーム仕上げ、背景色、名前と日付の刻印、写真インセット。"}}'::jsonb WHERE slug = 'varmala-preservation' AND translations IS NULL;
