UPDATE "Category" SET translations = '{"hi": {"name": "रेज़िन ज्वेलरी और कीचेन", "description": "सूखे फूलों और ग्लिटर के साथ इयररिंग, अंगूठियाँ, नेकलेस, ब्रेसलेट, चार्म और कीचेन। ₹100–₹2,000।"}, "gu": {"name": "રેઝિન જ્વેલરી અને કીચેન", "description": "સૂકાં ફૂલો અને ગ્લિટર સાથે ઇયરિંગ, વીંટીઓ, નેકલેસ, બ્રેસલેટ, ચાર્મ અને કીચેન. ₹100–₹2,000."}, "ar": {"name": "مجوهرات وميداليات راتنج", "description": "أقراط وخواتم وقلادات وأساور وتعليقات وميداليات مفاتيح مع أزهار مجففة ولمعة. ‏₹100–₹2,000."}, "es": {"name": "Joyería y llaveros de resina", "description": "Pendientes, anillos, collares, pulseras, dijes y llaveros con flores secas y purpurina. ₹100–₹2,000."}, "de": {"name": "Harzschmuck & Schlüsselanhänger", "description": "Ohrringe, Ringe, Ketten, Armbänder, Charms und Schlüsselanhänger mit Trockenblumen und Glitzer. ₹100–₹2.000."}, "fr": {"name": "Bijoux & porte-clés en résine", "description": "Boucles d''oreilles, bagues, colliers, bracelets, charms et porte-clés avec fleurs séchées et paillettes. ₹100–₹2 000."}, "zh": {"name": "树脂首饰与钥匙扣", "description": "耳环、戒指、项链、手链、吊饰与钥匙扣，镶嵌干花与闪粉。₹100–₹2,000。"}, "ja": {"name": "レジンアクセサリー・キーホルダー", "description": "ドライフラワーとグリッター入りのピアス、リング、ネックレス、ブレスレット、チャーム、キーホルダー。₹100〜₹2,000。"}}'::jsonb WHERE slug = 'resin-jewelry-keychains' AND translations IS NULL;
UPDATE "Category" SET translations = '{"hi": {"name": "रेज़िन होम डेकोर और एक्सेसरीज़", "description": "मोनोग्राम अक्षर, शिशु के पैर-हाथ के निशान की यादगारें, विवाह-वर्षगाँठ संरक्षण, वॉल आर्ट और कोस्टर सेट।"}, "gu": {"name": "રેઝિન હોમ ડેકોર અને એક્સેસરીઝ", "description": "મોનોગ્રામ અક્ષરો, બાળકના પગલાં-હથેળીની યાદગીરી, લગ્ન-વર્ષગાંઠ જતન, વૉલ આર્ટ અને કોસ્ટર સેટ."}, "ar": {"name": "ديكور منزلي وإكسسوارات من الراتنج", "description": "أحرف مونوغرام، تذكارات بصمات أقدام وأيدي الأطفال، حفظ ذكريات الزواج والذكرى السنوية، لوحات جدارية وأطقم قواعد أكواب."}, "es": {"name": "Decoración y accesorios de resina", "description": "Letras monograma, recuerdos de huellas de bebé, preservación de bodas y aniversarios, arte mural y sets de posavasos."}, "de": {"name": "Harz-Wohndekor & Accessoires", "description": "Monogramm-Buchstaben, Andenken mit Baby-Fuß- und Handabdrücken, Hochzeits- und Jubiläumskonservierung, Wandkunst und Untersetzer-Sets."}, "fr": {"name": "Décoration & accessoires en résine", "description": "Lettres monogrammes, souvenirs d''empreintes de bébé, préservation de mariage et d''anniversaire, art mural et sets de dessous de verre."}, "zh": {"name": "树脂家居装饰与配件", "description": "字母摆件、宝宝手足印纪念、婚礼与周年纪念封存、墙面艺术及杯垫套装。"}, "ja": {"name": "レジンホームデコ・小物", "description": "モノグラム文字、赤ちゃんの手形・足形キープセイク、結婚・記念日の保存加工、ウォールアート、コースターセット。"}}'::jsonb WHERE slug = 'resin-home-decor' AND translations IS NULL;
